export interface User {
  email: string;
}

/**
 * Type guard verifying an unknown payload is a User.
 */
export function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    "email" in value &&
    typeof (value as { email: unknown }).email === "string"
  );
}

