}

/**
 * Type guard verifying an unknown value is an ApiToken.
 */
export function isApiToken(payload: unknown): payload is ApiToken {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "token" in payload &&
    typeof (payload as { token: unknown }).token === "string"
  );
